import{_ as t,o,c as r,j as e,a as n}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/53-学着解读伴侣的信号.md","filePath":"books/attached/53-学着解读伴侣的信号.md","lastUpdated":1794316978000}'),s={name:"books/attached/53-学着解读伴侣的信号.md"};function l(d,a,_,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"学着解读伴侣的信号",tabindex:"-1"},[n("学着解读伴侣的信号 "),e("a",{class:"header-anchor",href:"#学着解读伴侣的信号","aria-label":'Permalink to "学着解读伴侣的信号"'},"​")],-1),e("p",null,"试想一下，你若是一个新晋家长，却无法理解小婴儿发出的信号。你根本不知道小孩子到底是饿了、累了、要抱抱还是想自己静静，是尿湿了还是生病了，这对于你来说很难；而对于孩子来说也是一种煎熬，他需要使劲地长时间哭泣，才能让你明白他的意思。",-1),e("p",null,"而回避型的人群常常感觉自己像那个家长，从伴侣在日常生活和交流所传递出的那些语言或非语言线索所中，正确地发掘出他们的心理状态，这实在不是回避型人群的强项。还有更重要的一点在于，基于自我依靠的信念，回避型人群常常会教诲自己，不要去在乎亲密之人的感受。他们会认为那不关自己的事，伴侣有义务照顾自己的情绪。而这种理解能力的匮乏，导致回避型人群的伴侣们总是抱怨自己没有得到应有的支持，也导致恋爱关系中的亲密感、温暖和满意度随之锐减。",-1),e("p",null,"明尼苏达州大学的心理学教授杰弗里·辛普森（Jeffrey Simpson）进行了一项研究，探讨成人依恋的各个倾向是如何在亲密关系中产生作用的，特别是在伴侣的关系比较紧张时，这个议题尤为重要。他还对伴侣彼此的共情能力进行了研究，也就是探究人们是否能够站在伴侣的角度来思考和感受事物的能力。在另一项与得克萨斯农工大学的斯蒂夫·罗尔斯（Steve Rholes）合作的研究中，他们设计了一项实验，用于测量不同依恋风格的人对于伴侣感受的感知能力是否有所差异。他们要求被试们在伴侣在场时，对图片上的异性形象进行魅力程度评价，并让他们预估伴侣得知这个评级以后的反应。在实验中，回避型人群对伴侣感受进行感知的精确程度，明显要比焦虑性人群差一些。回避型人群普遍觉得，即使他们对异性图片表示着迷，伴侣也不会有什么反应。而事实上，他们的伴侣心中是有些不快的。",-1),e("p",null,"约翰·格雷（John Gray）在他的畅销作品《男人来自火星，女人来自金星》（Men Are From Mars,Women Are From Venus）开篇，就提到了自己决定写这本书时灵光一闪的时刻，那就是妻子邦妮（Bonnie）遭受剧烈疼痛诞下宝贝女儿几天以后，约翰就回归了工作，而此时妻子的身体还在调养中。约翰晚上下班回家，只见妻子吃完了所有止痛药，向他抛出一句“整天忍受着疼痛，还要照顾小孩”。他看着十分沮丧的妻子，将她的焦虑不安误解为了愤怒，因此变得非常警觉小心，开始为自己的无辜作辩解。毕竟他事先的确不知道，妻子已经疼到需要把所有的止痛药吃了。那她又为什么不告诉他呢？在一番激烈的争执之后，约翰怒气冲冲地准备离开家，而妻子此时制止了他，说道：“别走，请别丢下我一个人。我从来没觉得那么需要你，我伤口还没愈合，晚上疼到睡不着，留下来陪我说说话好吗……”听到这里，约翰径直走向妻子，紧紧抱住了她。他接着写道：“那天，我第一次吵架之后没有丢下她，我也是头一次成功地在她最需要我的时候，给予了她应该的温暖。”",-1),e("p",null,"新家庭成员降生所带来的压力与责任，以及妻子高效的沟通，这件事情帮助约翰激发了自己的安全型相处机制。这件事也帮助约翰深刻理解到，对妻子幸福感的感知，是自己义不容辞的责任。约翰开始由一个只顾自己的感受，对伴侣的需要与不满回应十分被动的人，主动转变为一个带有安全型依恋倾向的人。这种转变对于回避型依恋风格的人其实并非易事，但如果你充分敞开心扉去关怀你的伴侣，了解他们的真实需要，也就可以实现这种转变。",-1)])])}const h=t(s,[["render",l]]);export{f as __pageData,h as default};
